{
  "hero": {
    "icon": "",
    "headline": "Count your tokens.\nLike beads on an abacus.",
    "markerLine": "Count your tokens.",
    "highlightPhrase": "Every token counts",
    "description": "— monitor budgets, optimize context, and cut AI costs before they add up. A VS Code extension, MCP server, and CLI that makes the invisible visible.",
    "installCmd": "ext install tokalator",
    "primaryCta": {
      "label": "Install Extension",
      "href": "https://marketplace.visualstudio.com/items?itemName=vfaraji89.tokalator"
    },
    "secondaryCta": {
      "label": "Learn More",
      "href": "/learn"
    }
  },
  "quickStart": {
    "title": "Quick Start",
    "steps": [
      "Install from the VS Code Marketplace or run `ext install tokalator`",
      "Click the Tokalator icon in the Activity Bar — the sidebar dashboard opens",
      "Type `@tokalator /count` in Copilot or Claude Chat to see your token budget",
      "Pin important files with `/pin` so they always stay in context",
      "Run `/optimize` to get a full health report on your context window"
    ],
    "technical": {
      "title": "Under the hood",
      "items": [
        {
          "label": "Tokenizers",
          "value": "Claude BPE (Anthropic), o200k_base (OpenAI), heuristic (Gemini)"
        },
        {
          "label": "Models",
          "value": "17 profiles — Claude 4.x, GPT-5.4, GPT-5.4 Mini, GPT-5.x Codex, GPT-4.1, o3, o4-mini, Gemini 3.x, Gemini 2.5"
        },
        {
          "label": "Caching",
          "value": "Prompt caching (Anthropic 90%), automatic (OpenAI 50%), context caching (Google 75%)"
        },
        {
          "label": "Scoring",
          "value": "Relevance from 0 to 1 based on imports, language, path similarity, recency, and diagnostics"
        },
        {
          "label": "MCP & CLI",
          "value": "count_tokens, estimate_budget, preview_turn, list_models — works in Claude Code via stdio MCP or as a standalone terminal CLI"
        }
      ]
    }
  },
  "commands": {
    "title": "All Commands",
    "description": "Available through @tokalator in VS Code Chat.",
    "items": [
      {
        "command": "/count",
        "description": "Show current token count and budget status"
      },
      {
        "command": "/breakdown",
        "description": "Show where your tokens are going"
      },
      {
        "command": "/optimize",
        "description": "Close low-relevance tabs to free up tokens"
      },
      {
        "command": "/pin",
        "description": "Pin a file so it's always included"
      },
      {
        "command": "/unpin",
        "description": "Unpin a file so it returns to normal relevance scoring"
      },
      {
        "command": "/instructions",
        "description": "List, count, and estimate tokens for instruction files in workspace"
      },
      {
        "command": "/model",
        "description": "Show or switch the active AI model"
      },
      {
        "command": "/compaction",
        "description": "Show per-turn token growth and compaction recommendations"
      },
      {
        "command": "/preview",
        "description": "Preview token cost of your next message before sending"
      },
      {
        "command": "/reset",
        "description": "Reset session state (chat turn counter)"
      },
      {
        "command": "/exit",
        "description": "End the current session and save summary"
      }
    ]
  },
  "shipped": {
    "title": "Recently Shipped",
    "subtitle": "What landed in v3.1.3.",
    "items": [
      {
        "name": "Claude Code via MCP",
        "description": "Real Claude BPE token counting inside Claude Code — count_tokens, estimate_budget, preview_turn, list_models via stdio MCP transport. Zero API calls.",
        "badge": "Live",
        "number": 1
      },
      {
        "name": "17 Model Profiles",
        "description": "Claude Opus/Sonnet 4.6, GPT-5.4, GPT-5.4 Mini, GPT-5.x Codex, Gemini 3.x — auto-detected from VS Code Copilot chat.",
        "badge": "Updated",
        "number": 2
      },
      {
        "name": "Economist-Style Calculator",
        "description": "Redesigned cost calculator with animated horizontal bar charts, cost-at-scale table, and stacked breakdown bars. No pie charts.",
        "badge": "New",
        "number": 3
      }
    ]
  },
  "comingSoon": {
    "title": "Coming Soon",
    "subtitle": "Next on the roadmap.",
    "items": [
      {
        "name": "Tokalator Pro",
        "description": "Team dashboards, historical token usage analytics, CI/CD budget gates, and custom model profiles.",
        "badge": "Pro",
        "number": 1
      },
      {
        "name": "Cursor Extension",
        "description": "Full Tokalator experience inside Cursor. Same dashboard, scoring, and chat commands — native to your workflow.",
        "badge": "Extension",
        "number": 2
      },
      {
        "name": "Per-Turn Budget Indicator",
        "description": "Live IDE status-bar widget showing estimated turns remaining before the conversation exhausts the context budget — the top community-requested feature.",
        "badge": "Feedback",
        "number": 3
      },
      {
        "name": "Secret Scanner (/secrets)",
        "description": "Detect and warn when API keys, tokens, or credentials appear in open tabs before they silently enter your AI context.",
        "badge": "Security",
        "number": 4
      }
    ]
  }
}

