18	    private readonly monitor: ContextMonitor,
19	  ) {
20	    this._snapshotListener = this.monitor.onDidUpdateSnapshot(snapshot => {
21	      this.postSnapshot(snapshot);
22	    });
23	  }
24	
25	  dispose(): void {
26	    this._snapshotListener.dispose();
27	  }
28	
29	  resolveWebviewView(
30	    webviewView: vscode.WebviewView,
31	    _context: vscode.WebviewViewResolveContext,
32	    _token: vscode.CancellationToken,
33	  ): void {
34	    this.view = webviewView;
35	
36	    webviewView.webview.options = {
37	      enableScripts: true,
38	      localResourceRoots: [this.extensionUri],
39	    };
40	
41	    // Keep webview alive when the sidebar is collapsed / user switches panels
42	    webviewView.onDidChangeVisibility(() => {
43	      if (webviewView.visible) {
44	        const snapshot = this.monitor.getLatestSnapshot();
45	        if (snapshot) {
46	          this.postSnapshot(snapshot);
47	        }
48	      }
49	    });
50	
51	    // Clear reference when the webview is disposed (panel closed completely)
52	    webviewView.onDidDispose(() => {
53	      this.view = undefined;
54	    });
55	
56	    webviewView.webview.html = this.getHtml(webviewView.webview);
57	
58	    webviewView.webview.onDidReceiveMessage(async (message) => {
59	      switch (message.command) {
60	        case 'optimize': {
61	          const closed = await this.monitor.optimizeTabs();
62	          vscode.window.showInformationMessage(
63	            closed.length > 0
64	              ? `Closed ${closed.length} tabs: ${closed.join(', ')}`
65	              : 'All tabs are relevant'
66	          );
67	          this.monitor.refresh();
68	          break;
69	        }
70	
71	        case 'pin': {
72	          this.monitor.pinFile(message.uri);
73	          break;
74	        }
75	
76	        case 'unpin': {
77	          this.monitor.unpinFile(message.uri);
78	          break;
79	        }
80	
81	        case 'closeTab': {
82	          const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
83	          const targetTab = allTabs.find(t => {
84	            if (t.input instanceof vscode.TabInputText) {
85	              return t.input.uri.toString() === message.uri;
86	            }
87	            return false;
88	          });
89	          if (targetTab) {
90	            await vscode.window.tabGroups.close(targetTab);
91	          }
92	          this.monitor.refresh();
93	          break;
94	        }
95	
96	        case 'openFile': {
97	          const doc = await vscode.workspace.openTextDocument(vscode.Uri.parse(message.uri));
98	          await vscode.window.showTextDocument(doc);
99	          break;
100	        }
101	
102	        case 'refresh': {
103	          this.monitor.refresh();
104	          break;
105	        }
106	
107	        case 'resetTurns': {
108	          this.monitor.resetChatTurns();
109	          break;
110	        }
111	
112	        case 'setModel': {
113	          await this.monitor.setModel(message.modelId);
114	          break;
115	        }
116	      }
117	    });
118	
119	    // Post existing snapshot immediately, then force a fresh refresh
120	    const snapshot = this.monitor.getLatestSnapshot();
121	    if (snapshot) {
122	      this.postSnapshot(snapshot);
123	    }
124	    // Trigger a fresh snapshot in case data changed while panel was hidden
125	    this.monitor.refresh();
126	  }
