128	  private postSnapshot(snapshot: ContextSnapshot): void {
129	    if (!this.view) { return; }
130	
131	    const serialized = {
132	      ...snapshot,
133	      pinnedFiles: Array.from(snapshot.pinnedFiles),
134	      tabs: snapshot.tabs.map(t => ({
135	        ...t,
136	        uri: t.uri.toString(),
137	      })),
138	      activeFile: snapshot.activeFile
139	        ? { ...snapshot.activeFile, uri: snapshot.activeFile.uri.toString() }
140	        : null,
141	      models: this.monitor.getModels().map(m => ({ id: m.id, label: m.label, provider: m.provider, contextWindow: m.contextWindow })),
142	      tokenizerType: snapshot.tokenizerType,
143	      tokenizerLabel: snapshot.tokenizerLabel,
144	      turnHistory: snapshot.turnHistory,
145	      budgetBreakdown: snapshot.budgetBreakdown,
146	    };
147	
148	    const lastSession = this.monitor.getLastSession();
149	    this.view.webview.postMessage({ type: 'snapshot', data: serialized, lastSession });
150	  }
