546	    function formatTimeAgo(iso) {
547	      var ms = Date.now() - new Date(iso).getTime();
548	      var mins = Math.floor(ms / 60000);
549	      if (mins < 60) return mins + 'm ago';
550	      var hours = Math.floor(mins / 60);
551	      if (hours < 24) return hours + 'h ago';
552	      var days = Math.floor(hours / 24);
553	      return days + 'd ago';
554	    }
