568	      const threshold = 0.3;
569	      const relevant = tabs.filter(t => t.relevanceScore >= threshold || t.isActive || t.isPinned);
570	      const distractors = tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
571	
572	      const modelOptions = (models || []).map(m =>
573	        '<option value="' + m.id + '"' + (m.id === modelId ? ' selected' : '') + '>' + m.label + ' (' + fmtTokens(m.contextWindow) + ')' + '</option>'
574	      ).join('');
