578	          <span class="header-icon">🧮</span>
579	          <span class="header-title">Tokalator</span>
580	        </div>
581	
582	        \${lastSession && lastSession.totalTurns > 0 ? \`
583	          <div class="last-session">
584	            <div class="last-session-header">
585	              <span class="last-session-title">Last Session</span>
586	              <span class="last-session-time">\${formatTimeAgo(lastSession.endedAt)}</span>
