1	import * as vscode from 'vscode';
2	import { TabInfo, ContextSnapshot, TurnSnapshot, SessionSummary } from './types';
3	import { TabRelevanceScorer } from './tabRelevanceScorer';
4	import { TokenBudgetEstimator } from './tokenBudgetEstimator';
5	import { TokenizerService } from './tokenizerService';
6	import { ModelProfile, MODEL_PROFILES, DEFAULT_MODEL_ID, getModel, findModel } from './modelProfiles';
7	import { SessionLogger } from './sessionLogger';
8	
9	const PINNED_FILES_KEY = 'tokalator.pinnedFiles';
10	const SELECTED_MODEL_KEY = 'tokalator.selectedModel';
11	const SESSION_KEY = 'tokalator.lastSession';
12	
13	/**
14	 * Core engine that tracks all editor state and produces real-time ContextSnapshots.
15	 *
16	 * Subscribes to:
17	 *  - Active editor changes
18	 *  - Tab open/close events
19	 *  - Text document changes
20	 *  - Diagnostics changes
21	 *
22	 * Emits:
23	 *  - onDidUpdateSnapshot: fires with a fresh ContextSnapshot after each state change
24	 */
25	export class ContextMonitor implements vscode.Disposable {
26	
27	  private readonly _onDidUpdateSnapshot = new vscode.EventEmitter<ContextSnapshot>();
28	  readonly onDidUpdateSnapshot = this._onDidUpdateSnapshot.event;
29	
30	  private readonly scorer = new TabRelevanceScorer();
31	  private readonly tokenizer = new TokenizerService();
32	  private readonly estimator = new TokenBudgetEstimator(this.tokenizer);
33	
34	  private pinnedFiles = new Set<string>();
35	  private chatTurnCount = 0;
36	  private turnHistory: TurnSnapshot[] = [];
37	  private lastEditTimestamps = new Map<string, number>();
38	  private disposables: vscode.Disposable[] = [];
39	  private refreshTimer: ReturnType<typeof setInterval> | undefined;
40	
41	  private latestSnapshot: ContextSnapshot | null = null;
42	  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
43	  private isRefreshing = false;
44	  private pendingRefresh = false;
45	
46	  private activeModel: ModelProfile;
47	  private workspaceFileTokens = 0;
48	  private workspaceFileCount = 0;
49	
50	  // Session tracking
51	  private peakTokens = 0;
52	  private peakPercent = 0;
53	  private fileEditCounts = new Map<string, number>();
54	
55	  // Opt-in session logger for research studies
56	  private sessionLogger: SessionLogger | null = null;
57	
58	  constructor(private readonly workspaceState?: vscode.Memento) {
59	    // Load persisted pinned files (normalize URIs for consistent matching)
60	    if (workspaceState) {
61	      const saved = workspaceState.get<string[]>(PINNED_FILES_KEY, []);
62	      this.pinnedFiles = new Set(saved.map(u => this.normalizeUri(u)));
63	    }
64	
65	    // Load persisted model selection
66	    const savedModelId = workspaceState?.get<string>(SELECTED_MODEL_KEY, DEFAULT_MODEL_ID) || DEFAULT_MODEL_ID;
67	    this.activeModel = getModel(savedModelId);
68	    this.estimator.setProvider(this.activeModel.provider);
69	
70	    // Scan workspace files on startup
71	    this.scanWorkspaceFiles();
72	
73	    // Debounced refresh to avoid perf issues from rapid event firing
74	    const debouncedRefresh = () => {
75	      if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
76	      this.debounceTimer = setTimeout(() => this.refresh(), 300);
77	    };
78	
79	    // Subscribe to VS Code events
80	    this.disposables.push(
81	      vscode.window.onDidChangeActiveTextEditor(() => debouncedRefresh()),
82	      vscode.window.onDidChangeTextEditorSelection(() => debouncedRefresh()),
83	      vscode.window.tabGroups.onDidChangeTabs(() => debouncedRefresh()),
84	      vscode.workspace.onDidChangeTextDocument(e => {
85	        const uri = e.document.uri.toString();
86	        this.lastEditTimestamps.set(uri, Date.now());
87	        this.fileEditCounts.set(uri, (this.fileEditCounts.get(uri) || 0) + 1);
88	        debouncedRefresh();
89	      }),
90	      vscode.workspace.onDidOpenTextDocument(() => debouncedRefresh()),
91	      // Clean up caches when documents close (memory leak fix)
92	      vscode.workspace.onDidCloseTextDocument(doc => {
93	        const uri = doc.uri.toString();
94	        this.lastEditTimestamps.delete(uri);
95	        this.estimator.clearCacheFor(uri);
96	        debouncedRefresh();
97	      }),
98	      vscode.languages.onDidChangeDiagnostics(() => debouncedRefresh()),
99	      // Sync model when settings change (skip if already on that model to avoid loop)
100	      vscode.workspace.onDidChangeConfiguration(e => {
101	        if (e.affectsConfiguration('tokalator.model')) {
102	          const cfg = vscode.workspace.getConfiguration('tokalator');
103	          const modelId = cfg.get<string>('model', DEFAULT_MODEL_ID);
104	          if (modelId !== this.activeModel.id) {
105	            this.setModel(modelId);
106	          }
107	        }
108	      }),
109	      // Sync when VS Code's available chat model set changes (e.g. provider rollout,
110	      // deprecation, or user installs a new Copilot extension)
111	      vscode.lm.onDidChangeChatModels(() => {
112	        void this.syncModelFromAvailableLMs();
113	      }),
114	    );
115	
116	    // Periodic refresh for time-based scoring (recency decay)
117	    const config = vscode.workspace.getConfiguration('tokalator');
118	    const interval = config.get<number>('autoRefreshInterval', 2000);
119	    this.refreshTimer = setInterval(() => this.refresh(), interval);
120	
121	    // Opt-in session logging for research studies
122	    if (config.get<boolean>('enableSessionLogging', false)) {
123	      this.sessionLogger = new SessionLogger();
124	      this.sessionLogger.startSession(this.activeModel.id);
125	    }
126	
127	    // Initial snapshot
128	    this.refresh();
129	  }
130	
131	  /**
132	   * Build a fresh snapshot and emit it.
133	   */
134	  async refresh(): Promise<void> {
135	    if (this.isRefreshing) {
136	      // Queue one pending refresh so the final state after rapid switching is captured
137	      this.pendingRefresh = true;
138	      return;
139	    }
140	    this.isRefreshing = true;
141	    this.pendingRefresh = false;
142	    try {
143	      const snapshot = await this.buildSnapshot();
144	      this.latestSnapshot = snapshot;
145	      this._onDidUpdateSnapshot.fire(snapshot);
146	
147	      // Log snapshot to session logger if enabled
148	      if (this.sessionLogger) {
149	        this.sessionLogger.logSnapshot(snapshot);
150	      }
151	    } finally {
152	      this.isRefreshing = false;
153	      // If events arrived while we were refreshing, run one more pass
154	      if (this.pendingRefresh) {
155	        this.pendingRefresh = false;
156	        void this.refresh();
157	      }
158	    }
159	  }
160	
161	  /**
162	   * Get the most recent snapshot without triggering a refresh.
163	   */
164	  getLatestSnapshot(): ContextSnapshot | null {
165	    return this.latestSnapshot;
166	  }
167	
168	  /**
169	   * Normalize a URI string for consistent Set matching.
170	   */
171	  private normalizeUri(uri: string): string {
172	    try {
173	      return vscode.Uri.parse(uri).toString();
174	    } catch {
175	      return uri;
176	    }
177	  }
178	
179	  /**
180	   * Pin a file URI so it's always scored as maximum relevance.
181	   */
182	  pinFile(uri: string): void {
183	    this.pinnedFiles.add(this.normalizeUri(uri));
184	    this.persistPins();
185	    this.refresh();
186	  }
187	
188	  /**
189	   * Unpin a file.
190	   */
191	  unpinFile(uri: string): void {
192	    this.pinnedFiles.delete(this.normalizeUri(uri));
193	    this.persistPins();
194	    this.refresh();
195	  }
196	
197	  /**
198	   * Clear all pins.
199	   */
200	  clearPins(): void {
201	    this.pinnedFiles.clear();
202	    this.persistPins();
203	    this.refresh();
204	  }
205	
206	  /**
207	   * Persist pinned files to workspace state.
208	   */
209	  private persistPins(): void {
210	    if (this.workspaceState) {
211	      this.workspaceState.update(PINNED_FILES_KEY, Array.from(this.pinnedFiles));
212	    }
213	  }
