242	  /**
243	   * Estimate the token cost of the *next* chat turn before sending.
244	   * This gives users a preview of what will be consumed.
245	   */
246	  async previewNextTurn(): Promise<{
247	    currentInput: number;
248	    nextTurnEstimate: number;
249	    conversationGrowth: number;
250	    outputReserved: number;
251	    remainingCapacity: number;
252	    percentAfterTurn: number;
253	    windowCapacity: number;
254	    warning: string | null;
255	  }> {
256	    await this.refresh();
257	    const snapshot = this.latestSnapshot;
258	    if (!snapshot) {
259	      return {
260	        currentInput: 0, nextTurnEstimate: 0, conversationGrowth: 800,
261	        outputReserved: this.activeModel.maxOutput, remainingCapacity: this.activeModel.contextWindow,
262	        percentAfterTurn: 0, windowCapacity: this.activeModel.contextWindow, warning: null,
263	      };
264	    }
265	
266	    // Each turn adds ~800 tokens (user message + assistant response)
267	    const perTurnCost = 800;
268	    const nextTurnInput = snapshot.totalEstimatedTokens + perTurnCost;
269	    const nextPercent = Math.min((nextTurnInput / snapshot.windowCapacity) * 100, 100);
270	    const remaining = Math.max(snapshot.windowCapacity - nextTurnInput - this.activeModel.maxOutput, 0);
271	
272	    let warning: string | null = null;
273	    if (nextPercent >= 90) {
274	      warning = 'Next turn will push you past 90% — high risk of context overflow';
275	    } else if (nextPercent >= 75) {
276	      warning = 'Approaching context limit — consider closing tabs or resetting';
277	    }
278	
279	    // Check if next turn crosses the rot threshold
280	    if (this.chatTurnCount + 1 >= this.activeModel.rotThreshold) {
281	      const rotMsg = `Turn ${this.chatTurnCount + 1} will cross context rot threshold (${this.activeModel.rotThreshold})`;
282	      warning = warning ? `${warning}. ${rotMsg}` : rotMsg;
283	    }
284	
285	    return {
286	      currentInput: snapshot.totalEstimatedTokens,
287	      nextTurnEstimate: nextTurnInput,
288	      conversationGrowth: perTurnCost,
289	      outputReserved: this.activeModel.maxOutput,
290	      remainingCapacity: remaining,
291	      percentAfterTurn: nextPercent,
292	      windowCapacity: snapshot.windowCapacity,
293	      warning,
294	    };
295	  }
