356	  /**
357	   * Build the full context snapshot.
358	   */
359	  private async buildSnapshot(): Promise<ContextSnapshot> {
360	    const config = vscode.workspace.getConfiguration('tokalator');
361	    // Use windowSize setting as override only when it differs from the default (1,000,000)
362	    const configWindowSize = config.get<number>('windowSize', 1000000);
363	    const windowCapacity = configWindowSize !== 1000000 ? configWindowSize : this.activeModel.contextWindow;
364	    const rotWarning = this.activeModel.rotThreshold;
365	
366	    // 1. Gather all open tabs
367	    let tabs = this.gatherTabs();
368	
369	    // 2. Estimate tokens for each tab
370	    tabs = await this.estimator.estimateAllTabs(tabs);
371	
372	    // 3. Score relevance
373	    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);
374	
375	    // 4. Sort by relevance (highest first)
376	    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);
377	
378	    // 5. Gather diagnostics summary
379	    const diagnosticsSummary = this.gatherDiagnosticsSummary();
380	
381	    // 6. Count instruction files in workspace
382	    const instructionFiles = await this.countInstructionFiles();
383	
384	    // 7. Compute budget
385	    const budget = this.estimator.computeBudget(
386	      tabs,
387	      this.chatTurnCount,
388	      instructionFiles,
389	      windowCapacity
390	    );
391	
392	    // Track peak usage for session summary
393	    if (budget.used > this.peakTokens) {
394	      this.peakTokens = budget.used;
395	      this.peakPercent = budget.percent;
396	    }
397	
398	    // 8. Determine budget level (simplified from percentage)
399	    let budgetLevel: 'low' | 'medium' | 'high';
400	    if (budget.percent > 85) {
401	      budgetLevel = 'high';
402	    } else if (budget.percent > 60) {
403	      budgetLevel = 'medium';
404	    } else {
405	      budgetLevel = 'low';
406	    }
407	
408	    // 9. Determine health and reasons
409	    const healthReasons: string[] = [];
410	    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';
411	
412	    if (budgetLevel === 'high') {
413	      contextHealth = 'critical';
414	      healthReasons.push('Token budget is high — context overflow risk');
415	    } else if (budgetLevel === 'medium') {
416	      contextHealth = 'warning';
417	      healthReasons.push('Token budget is medium — consider closing unused tabs');
418	    }
419	
420	    if (this.chatTurnCount >= rotWarning) {
421	      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
422	      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
423	    }
424	
425	    const distractors = tabs.filter(t => {
426	      const threshold = config.get<number>('relevanceThreshold', 0.3);
427	      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
428	    });
429	    if (distractors.length > 3) {
430	      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
431	      healthReasons.push(`${distractors.length} low-relevance tabs open`);
432	    }
433	
434	    if (healthReasons.length === 0) {
435	      healthReasons.push('Token budget looks good');
436	    }
437	
438	    const activeFile = tabs.find(t => t.isActive) || null;
439	
440	    return {
441	      timestamp: Date.now(),
442	      activeFile,
443	      tabs,
444	      pinnedFiles: this.pinnedFiles,
445	      totalEstimatedTokens: budget.used,
446	      windowCapacity,
447	      usagePercent: budget.percent,
448	      budgetLevel,
449	      diagnosticsSummary,
450	      chatTurnCount: this.chatTurnCount,
451	      contextHealth,
452	      healthReasons,
453	      modelId: this.activeModel.id,
454	      modelLabel: this.activeModel.label,
455	      workspaceFileCount: this.workspaceFileCount,
456	      workspaceFileTokens: this.workspaceFileTokens,
457	      tokenizerType: this.tokenizer.getTokenizerType(this.activeModel.provider),
458	      tokenizerLabel: this.tokenizer.getTokenizerLabel(this.activeModel.provider),
459	      turnHistory: [...this.turnHistory],
460	      budgetBreakdown: budget.breakdown,
461	    };
462	  }
