464	  /**
465	   * Gather TabInfo from all open tab groups.
466	   */
467	  private gatherTabs(): TabInfo[] {
468	    const tabs: TabInfo[] = [];
469	    const seenUris = new Set<string>();
470	    const workspaceFolders = vscode.workspace.workspaceFolders || [];
471	
472	    for (const group of vscode.window.tabGroups.all) {
473	      for (const tab of group.tabs) {
474	        if (!(tab.input instanceof vscode.TabInputText)) { continue; }
475	
476	        const uri = tab.input.uri;
477	        const uriKey = uri.toString();
478	
479	        // Skip duplicate URIs (same file open in split panes)
480	        if (seenUris.has(uriKey)) { continue; }
481	        seenUris.add(uriKey);
482	
483	        const fsPath = uri.fsPath;
484	
485	        // Find the matching workspace folder for correct relative path in multi-root workspaces
486	        const matchingFolder = workspaceFolders.find(f => fsPath.startsWith(f.uri.fsPath));
487	        const relativePath = matchingFolder
488	          ? fsPath.replace(matchingFolder.uri.fsPath, '').replace(/^[/\\]/, '')
489	          : fsPath;
490	
491	        // Get language ID from open documents
492	        const openDoc = vscode.workspace.textDocuments.find(
493	          d => d.uri.toString() === uri.toString()
494	        );
495	        const languageId = openDoc?.languageId || this.guessLanguage(fsPath);
496	
497	        // Get diagnostics for this file
498	        const diagnostics = vscode.languages.getDiagnostics(uri);
499	        const diagnosticCount = diagnostics.length;
500	
501	        // Get last edit timestamp
502	        const lastEdit = this.lastEditTimestamps.get(uri.toString()) || 0;
503	
504	        tabs.push({
505	          uri,
506	          label: tab.label,
507	          languageId,
508	          relativePath,
509	          estimatedTokens: 0,   // filled later by estimator
510	          relevanceScore: 0,     // filled later by scorer
511	          relevanceReason: '',
512	          isActive: tab.isActive,
513	          isDirty: tab.isDirty,
514	          isPinned: this.pinnedFiles.has(uri.toString()),
515	          diagnosticCount,
516	          lastEditTimestamp: lastEdit,
517	        });
518	      }
519	    }
520	
521	    return tabs;
522	  }
