524	  /**
525	   * Aggregate diagnostics across all open files.
526	   */
527	  private gatherDiagnosticsSummary(): { errors: number; warnings: number; info: number } {
528	    const allDiags = vscode.languages.getDiagnostics();
529	    let errors = 0, warnings = 0, info = 0;
530	
531	    for (const [, diags] of allDiags) {
532	      for (const d of diags) {
533	        switch (d.severity) {
534	          case vscode.DiagnosticSeverity.Error: errors++; break;
535	          case vscode.DiagnosticSeverity.Warning: warnings++; break;
536	          default: info++; break;
537	        }
538	      }
539	    }
540	
541	    return { errors, warnings, info };
542	  }
