548	    try {
549	      const exclude = '**/node_modules/**';
550	      const [instrFiles, copilotInstr, claudeMd, agentsMd, cursorRules] = await Promise.all([
551	        vscode.workspace.findFiles('**/*.instructions.md', exclude, 20),
552	        vscode.workspace.findFiles('.github/copilot-instructions.md', undefined, 1),
553	        vscode.workspace.findFiles('**/CLAUDE.md', exclude, 5),
554	        vscode.workspace.findFiles('**/AGENTS.md', exclude, 5),
555	        vscode.workspace.findFiles('**/.cursorrules', exclude, 5),
556	      ]);
557	      return instrFiles.length + copilotInstr.length + claudeMd.length + agentsMd.length + cursorRules.length;
558	    } catch {
559	      return 0;
560	    }
