563	  /**
564	   * Guess language from file extension.
565	   */
566	  private guessLanguage(fsPath: string): string {
567	    const ext = fsPath.split('.').pop()?.toLowerCase() || '';
568	    const map: Record<string, string> = {
569	      ts: 'typescript', tsx: 'typescriptreact', js: 'javascript', jsx: 'javascriptreact',
570	      py: 'python', go: 'go', rs: 'rust', java: 'java', rb: 'ruby',
571	      md: 'markdown', json: 'json', yml: 'yaml', yaml: 'yaml',
572	      css: 'css', html: 'html', sh: 'shellscript', sql: 'sql',
573	    };
574	    return map[ext] || ext;
575	  }
