577	  /**
578	   * Called when vscode.lm.onDidChangeChatModels fires.
579	   * If the current model is no longer available, switches to the best known
580	   * alternative and notifies the user.
581	   */
582	  async syncModelFromAvailableLMs(): Promise<void> {
583	    const available = await vscode.lm.selectChatModels();
584	    if (!available.length) { return; }
585	
586	    const current = this.activeModel;
587	
588	    // Check if any available model maps to our current profile — still good
589	    const stillPresent = available.some(lm =>
590	      (findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name))?.id === current.id
591	    );
592	    if (stillPresent) { return; }
593	
594	    // Current model gone — find the best available substitute
595	    for (const lm of available) {
596	      const match = findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name);
597	      if (match) {
598	        await this.setModel(match.id);
599	        vscode.window.showInformationMessage(
600	          `Tokalator: "${current.label}" is no longer available. Switched to "${match.label}".`
601	        );
602	        return;
603	      }
604	    }
605	  }
