332	    stream.markdown(`## Context Growth\n\n`);
333	
334	    // Current budget breakdown
335	    stream.markdown(`### Budget Breakdown\n\n`);
336	    stream.markdown(`| Category | Tokens | % of Window |\n|---|---|---|\n`);
337	    const entries: [string, number][] = [
338	      ['Files', breakdown.files],
339	      ['System prompt', breakdown.systemPrompt],
340	      ['Instructions', breakdown.instructions],
341	      ['Conversation', breakdown.conversation],
342	      ['Output reserve', breakdown.outputReservation],
343	    ];
344	    for (const [label, tokens] of entries) {
345	      const pct = ((tokens / snapshot.windowCapacity) * 100).toFixed(1);
346	      stream.markdown(`| ${label} | ~${this.fmtTokens(tokens)} | ${pct}% |\n`);
347	    }
348	    stream.markdown(`| **Total** | **~${this.fmtTokens(snapshot.totalEstimatedTokens)}** | **${snapshot.usagePercent.toFixed(1)}%** |\n\n`);
349	
350	    // Per-turn history table
351	    if (history.length > 0) {
352	      stream.markdown(`### Turn History\n\n`);
353	      stream.markdown(`| Turn | Input | Files | Overhead | Tabs | Pinned |\n|---|---|---|---|---|---|\n`);
354	
355	      for (const t of history) {
356	        stream.markdown(`| ${t.turn} | ~${this.fmtTokens(t.inputTokens)} | ~${this.fmtTokens(t.fileTokens)} | ~${this.fmtTokens(t.overheadTokens)} | ${t.tabCount} | ${t.pinnedCount} |\n`);
357	      }
358	
359	      // Growth analysis
360	      stream.markdown(`\n### Growth Analysis\n\n`);
361	
362	      const avgGrowth = history.length >= 2
363	        ? (history[history.length - 1].inputTokens - history[0].inputTokens) / (history.length - 1)
364	        : 0;
365	
366	      const firstFile = history[0].fileTokens;
367	      const lastFile = history[history.length - 1].fileTokens;
368	      const fileTrend = lastFile > firstFile * 1.1 ? 'growing' : lastFile < firstFile * 0.9 ? 'shrinking' : 'stable';
369	
370	      stream.markdown(`- **Conversation cost:** ~800 tokens/turn (estimated)\n`);
371	      if (history.length >= 2) {
372	        stream.markdown(`- **Input growth rate:** ~${this.fmtTokens(Math.round(avgGrowth))}/turn\n`);
373	      }
374	      stream.markdown(`- **File tokens:** ${fileTrend} (${this.fmtTokens(firstFile)} → ${this.fmtTokens(lastFile)})\n`);
375	      stream.markdown(`- **Output reserved:** ~${this.fmtTokens(model.maxOutput)} per response\n\n`);
376	    } else {
377	      stream.markdown(`*No turn history yet.* Use \`@tokalator /pin\`, \`/optimize\`, or \`/unpin\` to start tracking.\n\n`);
378	    }
379	
380	    // Actionable suggestions
381	    const suggestions: string[] = [];
382	
383	    const config = vscode.workspace.getConfiguration('tokalator');
384	    const threshold = config.get<number>('relevanceThreshold', 0.3);
385	    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
386	    if (distractors.length > 0) {
387	      const saveable = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
388	      suggestions.push(`Close ${distractors.length} low-relevance tabs to save ~${this.fmtTokens(saveable)} tokens`);
389	    }
390	
391	    const turnsLeft = model.rotThreshold - snapshot.chatTurnCount;
392	    if (turnsLeft <= 5 && turnsLeft > 0) {
393	      suggestions.push(`${turnsLeft} turns until context rot threshold (${model.rotThreshold}) — consider \`/reset\``);
394	    } else if (turnsLeft <= 0) {
395	      suggestions.push(`Past context rot threshold (${model.rotThreshold} turns) — run \`/reset\` to clear`);
396	    }
397	
398	    const inputPct = snapshot.usagePercent;
399	    if (inputPct >= 80) {
400	      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — compaction point reached`);
401	    } else if (inputPct >= 60) {
402	      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — approaching compaction point`);
403	    }
404	
405	    const pinnedCount = snapshot.pinnedFiles.size;
406	    if (pinnedCount > 5) {
407	      suggestions.push(`${pinnedCount} files pinned — unpin files you're done with`);
408	    }
409	
410	    if (suggestions.length > 0) {
411	      stream.markdown(`### Recommendations\n\n`);
412	      for (const s of suggestions) {
413	        stream.markdown(`- ${s}\n`);
414	      }
415	    } else {
416	      stream.markdown(`> Context looks healthy — no compaction needed yet.\n`);
417	    }
418	
419	    return {};
420	  }
