649	  private async resolveUrisFromInput(input: string): Promise<vscode.Uri[]> {
650	    const normalized = this.normalizeInputPath(input);
651	    if (!normalized) { return []; }
652	
653	    if (this.isAbsolutePath(normalized)) {
654	      const absoluteUri = vscode.Uri.file(normalized);
655	      if (await this.fileExists(absoluteUri)) {
656	        return [absoluteUri];
657	      }
658	    }
659	
660	    const relativeUri = await this.tryResolveRelative(normalized);
661	    if (relativeUri) {
