680	  private async tryResolveRelative(relativePath: string): Promise<vscode.Uri | null> {
681	    const trimmed = relativePath.replace(/^(\.\\|\.\/)+/, '').replace(/^\\+|^\/+/, '');
682	    if (!trimmed) { return null; }
683	    const folders = vscode.workspace.workspaceFolders || [];
684	    for (const folder of folders) {
685	      const candidate = vscode.Uri.file(path.join(folder.uri.fsPath, trimmed));
686	      if (await this.fileExists(candidate)) {
687	        return candidate;
688	      }
689	    }
690	    return null;
691	  }
