694	    const globTarget = target.replace(/^[/\\]+/, '').replace(/\\/g, '/');
695	    if (!globTarget) { return []; }
696	    try {
697	      return await vscode.workspace.findFiles(`**/${globTarget}`, '**/node_modules/**', 5);
698	    } catch {
699	      return [];
700	    }
