703	  private async fileExists(uri: vscode.Uri): Promise<boolean> {
704	    try {
705	      const stat = await vscode.workspace.fs.stat(uri);
706	      return stat.type === vscode.FileType.File;
707	    } catch {
708	      return false;
709	    }
710	  }
