712	  private dedupeUris(uris: vscode.Uri[]): vscode.Uri[] {
713	    const seen = new Set<string>();
714	    const unique: vscode.Uri[] = [];
715	    for (const uri of uris) {
716	      const key = uri.toString();
717	      if (!seen.has(key)) {
718	        seen.add(key);
719	        unique.push(uri);
720	      }
721	    }
722	    return unique;
723	  }
