725	  /**
726	   * Auto-detect the model from the Copilot chat request and sync Tokalator to it.
727	   * Tries to match by family → id → name so switching models in the Copilot UI
728	   * automatically updates context window and tokenizer without any manual step.
729	   */
730	  private async syncModelFromRequest(request: vscode.ChatRequest): Promise<void> {
731	    const lm = request.model;
732	    if (!lm) { return; }
733	
734	    const current = this.monitor.getActiveModel();
735	    // Try family first (most stable identifier), then full id, then display name
736	    const match = findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name);
737	
738	    if (match) {
739	      if (match.id !== current.id) {
740	        await this.monitor.setModel(match.id);
741	      }
742	      return;
743	    }
744	
745	    // Unknown model — warn once per session so the user knows counts may be off
746	    const unknownKey = lm.family || lm.id || lm.name;
747	    if (!this._warnedUnknownModels.has(unknownKey)) {
748	      this._warnedUnknownModels.add(unknownKey);
749	      vscode.window.showWarningMessage(
750	        `Tokalator: unrecognized model "${lm.name}" (family: "${lm.family}") — token counts may be inaccurate. Add it to models.json and run npm run generate-models.`
751	      );
752	    }
753	  }
754	
755	  dispose(): void {
756	    this.participant.dispose();
757	  }
758	}
