/**
 * Claude model profiles for Tokalator MCP.
 * Scoped to Anthropic models only.
 */

export interface ModelProfile {
  id: string;
  label: string;
  provider: 'anthropic';
  contextWindow: number;
  maxOutput: number;
  rotThreshold: number;
}

export const MODEL_PROFILES: ModelProfile[] = [
  { id: 'claude-opus-4.6',   label: 'Claude Opus 4.6',   provider: 'anthropic', contextWindow: 1_000_000, maxOutput: 32_000, rotThreshold: 40 },
  { id: 'claude-sonnet-4.5', label: 'Claude Sonnet 4.5', provider: 'anthropic', contextWindow:   200_000, maxOutput: 16_000, rotThreshold: 20 },
  { id: 'claude-sonnet-4',   label: 'Claude Sonnet 4',   provider: 'anthropic', contextWindow:   200_000, maxOutput: 16_000, rotThreshold: 20 },
  { id: 'claude-haiku-4.5',  label: 'Claude Haiku 4.5',  provider: 'anthropic', contextWindow:   200_000, maxOutput: 64_000, rotThreshold: 15 },
];

export const DEFAULT_MODEL_ID = 'claude-opus-4.6';

/**
 * Find a model by partial ID or label match.
 * Priority: exact id → exact label → startsWith → contains.
 */
export function findModel(query: string): ModelProfile | undefined {
  const q = query.toLowerCase().replace(/[^a-z0-9.]/g, '');
  if (!q) return undefined;

  const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9.]/g, '');

  return (
    MODEL_PROFILES.find(m => norm(m.id) === q) ||
    MODEL_PROFILES.find(m => norm(m.label) === q) ||
    MODEL_PROFILES.find(m => norm(m.id).startsWith(q) || norm(m.label).startsWith(q)) ||
    MODEL_PROFILES.find(m => norm(m.id).includes(q) || norm(m.label).includes(q))
  );
}

/** Get model by exact ID, falling back to default. */
export function getModel(id: string): ModelProfile {
  return (
    MODEL_PROFILES.find(m => m.id === id) ||
    MODEL_PROFILES.find(m => m.id === DEFAULT_MODEL_ID)!
  );
}

{
  "version": "3.1.3",
  "icon": "⬡",
  "headline": "Real-time context monitoring.\nInside your editor.",
  "highlightPhrase": "context monitoring",
  "tagline": "Track token budgets with real tokenizers, score tab relevance, and manage context — available as a VS Code extension, MCP server, and CLI.",
  "installCmd": "ext install vfaraji89.tokalator",
  "vsCodeMinVersion": "1.99",
  "githubUrl": "https://github.com/vfaraji89/tokalator",
  "license": "MIT",
  "features": [
    {
      "icon": "▣",
      "name": "Token Budget Dashboard",
      "description": "Activity bar sidebar panel showing real-time token usage, budget meter, per-file breakdown, and active tokenizer info.",
      "command": "View via sidebar icon",
      "number": 1
    },
    {
      "icon": "◎",
      "name": "@tokalator Chat Participant",
      "description": "Eleven chat commands for inline budget management directly in Copilot Chat.",
      "command": "@tokalator /count, /optimize, /breakdown, /pin, /unpin, /instructions, /model, /compaction, /preview, /reset, /exit",
      "number": 2
    },
    {
      "icon": "⬡",
      "name": "Tab Relevance Scoring",
      "description": "Ranks open tabs by relevance using import analysis, path similarity, edit recency, and diagnostics.",
      "command": "tokalator.optimize",
      "number": 3
    },
    {
      "icon": "⊕",
      "name": "Model-Specific Tokenizers",
      "description": "Real BPE tokenizers per provider — Claude BPE for Anthropic, o200k_base for OpenAI. No more guessing at 4 chars per token.",
      "command": "@tokalator /model",
      "number": 4
    },
    {
      "icon": "◇",
      "name": "17 Model Profiles",
      "description": "Built-in profiles for Claude Opus/Sonnet/Haiku 4.x, GPT-5.4, GPT-5.4 Mini, GPT-5.2/5.1 Codex, GPT-4.1, o3, o4-mini, Gemini 3.x Pro/Flash, Gemini 2.5 Pro. Context windows and rot thresholds auto-configured.",
      "command": "Settings: tokalator.model",
      "number": 5
    },
    {
      "icon": "⚠",
      "name": "Context Rot Warnings",
      "description": "Warns when conversation turns exceed the model's threshold. Each model has its own rot limit based on benchmarks.",
      "command": "Automatic",
      "number": 6
    },
    {
      "icon": "⊕",
      "name": "Pinned Files",
      "description": "Pin important files so they are always treated as high-relevance in context scoring.",
      "command": "@tokalator /pin <file>",
      "number": 7
    },
    {
      "icon": "◈",
      "name": "Instruction File Scanner",
      "description": "Detects and tokenizes instruction files silently injected into every prompt: .github/copilot-instructions.md, CLAUDE.md, AGENTS.md, .cursorrules, and .instructions.md. Reveals hidden per-file token cost.",
      "command": "@tokalator /instructions",
      "number": 8
    },
    {
      "icon": "▹",
      "name": "Next Turn Preview",
      "description": "See estimated token cost of your next message before sending. Dashboard shows a live preview box with growth projections and overflow warnings.",
      "command": "@tokalator /preview",
      "number": 9
    },
    {
      "icon": "◉",
      "name": "Session Management",
      "description": "Track per-turn context growth with compaction analysis. Reset sessions, save summaries, and see last session stats on activation.",
      "command": "@tokalator /compaction, /reset, /exit",
      "number": 10
    },
    {
      "icon": "⬡",
      "name": "MCP Server for Claude Code",
      "description": "Brings real Claude BPE token counting into Claude Code and any MCP-capable agent via stdio transport. Four tools: count_tokens, estimate_budget, preview_turn, list_models. Zero API calls — fully offline.",
      "command": "claude mcp add --transport stdio tokalator -- node tokalator-mcp/build/index.js",
      "number": 11
    },
    {
      "icon": "◆",
      "name": "CLI — tokalator count, budget, preview, models",
      "description": "Standalone terminal tool for non-VS Code workflows. Count tokens in files, get full budget breakdowns, preview next-turn cost, and list Claude model profiles — all from the command line.",
      "command": "npm install -g . (from tokalator-mcp/) · tokalator count src/main.ts · tokalator budget src/**/*.ts",
      "number": 12
    }
  ],
  "stats": {
    "marketplaceAcquisitions": 156,
    "marketplaceInstalls": 19,
    "marketplacePageViews": 188,
    "conversionRate": "82.98%",
    "period": "First 30 days (Feb 4 – Mar 6, 2026)",
    "communityDevelopers": 220,
    "communitySessions": 3,
    "communitySessionNames": ["iLab / Kariyer.net", "SaaS Bridge", "TechCareer"],
    "communitySessionDetails": [
      { "name": "iLab / Kariyer.net", "attendees": 50, "note": "Internal deployment — engineers used the extension for one week" },
      { "name": "SaaS Bridge", "attendees": 90, "note": "Istanbul, March 4 2026" },
      { "name": "TechCareer", "attendees": 80, "note": "Istanbul, March 5 2026" }
    ],
    "unitTests": 124,
    "testFiles": 6
  },
  "settings": [
    {
      "key": "tokalator.model",
      "default": "claude-opus-4.6",
      "description": "AI model to calculate context budget against. Sets tokenizer, context window, and rot threshold automatically."
    },
    {
      "key": "tokalator.relevanceThreshold",
      "default": "0.3",
      "description": "Tabs below this relevance score are marked as distractors (0–1)"
    },
    {
      "key": "tokalator.windowSize",
      "default": "1,000,000",
      "description": "Override context window size in tokens. Leave at default to use the selected model's window."
    },
    {
      "key": "tokalator.contextRotWarningTurns",
      "default": "20",
      "description": "Warn about context rot after this many chat turns"
    },
    {
      "key": "tokalator.autoRefreshInterval",
      "default": "2000",
      "description": "Dashboard refresh interval in milliseconds"
    }
  ],
  "architecture": [
    {
      "layer": "Core Engine",
      "purpose": "Subscribes to VS Code editor events (active editor, tab open/close, document edits, diagnostics). Builds ContextSnapshot records, manages pinned files and model selection via workspaceState. All handlers debounced 300 ms.",
      "number": 1
    },
    {
      "layer": "Tokenizer Service",
      "purpose": "Provider-specific BPE tokenizers — claude-tokenizer for Anthropic, o200k_base (js-tiktoken) for OpenAI, heuristic (~4 chars/token) for Gemini. Lazy-loaded and cached per document URI + version.",
      "number": 2
    },
    {
      "layer": "Relevance Scorer",
      "purpose": "Scores each open tab R ∈ [0, 1]: language match (0.25), import analysis (0.30), path similarity (0.20), edit recency (0.15), diagnostics (0.10). Pinned and active tabs override to R = 1.0.",
      "number": 3
    },
    {
      "layer": "Context Optimizer",
      "purpose": "Identifies distractor tabs (R < 0.3) and closes them via /optimize or the Optimize Tabs button. Reduces attention dilution by removing files unlikely to contribute to the current task.",
      "number": 4
    },
    {
      "layer": "Chat Participant",
      "purpose": "@tokalator with 11 slash commands — /count, /optimize, /breakdown, /pin, /unpin, /instructions, /model, /compaction, /preview, /reset, /exit.",
      "number": 5
    },
    {
      "layer": "MCP Server & CLI (tokalator-mcp)",
      "purpose": "Separate component: exposes count_tokens, estimate_budget, preview_turn, list_models to Claude Code via stdio MCP transport. Also ships a standalone CLI binary for terminal workflows.",
      "number": 6
    }
  ],
  "tokenizers": [
    {
      "provider": "Anthropic",
      "models": "Opus 4.6, Opus 4.5, Sonnet 4.6, Sonnet 4.5, Sonnet 4, Haiku 4.5",
      "tokenizer": "Claude BPE",
      "source": "@anthropic-ai/tokenizer"
    },
    {
      "provider": "OpenAI",
      "models": "GPT-5.4, GPT-5.4 Mini, GPT-5.2 Codex, GPT-5.1 Codex, GPT-4.1, o3, o4-mini",
      "tokenizer": "o200k_base",
      "source": "js-tiktoken"
    },
    {
      "provider": "Google",
      "models": "Gemini 3.1 Pro, Gemini 3 Pro, Gemini 3 Flash, Gemini 2.5 Pro",
      "tokenizer": "Heuristic",
      "source": "~4 chars/token (no official JS tokenizer)"
    }
  ],
  "installMethods": {
    "marketplace": {
      "title": "Marketplace",
      "icon": "◉",
      "command": "ext install vfaraji89.tokalator",
      "note": "Requires VS Code 1.99+"
    },
    "vsix": {
      "title": "VSIX",
      "icon": "◇",
      "steps": [
        "Download tokalator-3.1.3.vsix from releases",
        "Cmd+Shift+P → Extensions: Install from VSIX...",
        "Select the downloaded .vsix file"
      ],
      "command": "code --install-extension tokalator-3.1.3.vsix"
    },
    "source": {
      "title": "Build from Source",
      "icon": "◆",
      "command": "git clone https://github.com/vfaraji89/tokalator.git\ncd tokalator/tokalator-extension-vs\nnpm install\nnpm run compile"
    },
    "cli": {
      "title": "CLI (npm)",
      "icon": "◆",
      "note": "Requires Node.js 18+",
      "steps": [
        "git clone https://github.com/vfaraji89/tokalator.git",
        "cd tokalator/tokalator-mcp && npm install && npm run build",
        "npm install -g ."
      ],
      "command": "tokalator count src/main.ts\ntokalator budget src/**/*.ts\ntokalator preview 42000\ntokalator models"
    },
    "mcp": {
      "title": "MCP Server (Claude Code)",
      "icon": "⬡",
      "note": "Requires Node.js 18+ and Claude Code",
      "steps": [
        "Build the CLI first (see above)",
        "claude mcp add --transport stdio tokalator -- node tokalator-mcp/build/index.js",
        "In Claude Code: /mcp → verify tokalator is listed"
      ],
      "command": "claude mcp add --transport stdio tokalator -- node tokalator-mcp/build/index.js"
    }
  }
}

